    28→ * OF THE POSSIBILITY OF SUCH DAMAGE.
    29→ */
    30→package com.jcabi.http.response;
    31→
    32→import com.jcabi.aspects.Immutable;
    33→import com.jcabi.http.Request;
    34→import com.jcabi.http.Response;
    35→import com.jcabi.log.Logger;
    36→import java.net.HttpCookie;
    37→import java.net.URI;
    38→import java.util.Collections;
    39→import java.util.Iterator;
    40→import java.util.List;
    41→import java.util.Map;
    42→import javax.ws.rs.core.Cookie;
    43→import javax.ws.rs.core.HttpHeaders;
    44→import lombok.EqualsAndHashCode;
    45→import org.hamcrest.CustomMatcher;
    46→import org.hamcrest.Matcher;
    47→import org.hamcrest.MatcherAssert;
    48→import org.hamcrest.Matchers;
    49→
    50→/**
    51→ * REST response.
    52→ *
    53→ * <p>This response decorator is able to make basic assertions on
    54→ * HTTP response and manipulate with it afterwords, for example:
    55→ *
    56→ * <pre> String name = new JdkRequest("http://my.example.com")
    57→ *   .fetch()
    58→ *   .as(RestResponse.class)
    59→ *   .assertStatus(200)
    60→ *   .assertBody(Matchers.containsString("hello, world!"))
    61→ *   .assertHeader("Content-Type", Matchers.hasItem("text/plain"))
    62→ *   .jump(URI.create("/users"))
    63→ *   .fetch();</pre>
    64→ *
    65→ * <p>Method {@link #jump(URI)} creates a new instance of class
    66→ * {@link Request} with all cookies transferred from the current one.
    67→ *
    68→ * <p>The class is immutable and thread-safe.
    69→ *
    70→ * @since 0.8
    71→ */
    72→@Immutable
    73→@EqualsAndHashCode(callSuper = true)
    74→@SuppressWarnings("PMD.TooManyMethods")
    75→public final class RestResponse extends AbstractResponse {
    76→
    77→    /**
    78→     * Public ctor.
    79→     * @param resp Response
    80→     */
    81→    public RestResponse(final Response resp) {
    82→        super(resp);
    83→    }
    84→
    85→    /**
    86→     * Assert using custom matcher.
    87→     * @param matcher The matcher to use
    88→     * @return The same object
    89→     */
    90→    public RestResponse assertThat(final Matcher<Response> matcher) {
    91→        MatcherAssert.assertThat(
    92→            String.format("HTTP response is not valid: %s", this),
    93→            this,
    94→            matcher
    95→        );
    96→        return this;
    97→    }
    98→
    99→    /**
   100→     * Verifies HTTP response status code against the provided absolute value,
   101→     * and throws {@link AssertionError} in case of mismatch.
   102→     * @param status Expected status code
   103→     * @return The same object
   104→     */
   105→    public RestResponse assertStatus(final int status) {
   106→        final String message = String.format(
   107→            "HTTP response with status %d", status
   108→        );
   109→        MatcherAssert.assertThat(
   110→            String.format(
   111→                "HTTP response status is not equal to %d:%n%s",
   112→                status, this
   113→            ),
   114→            this,
   115→            new RestResponse.StatusMatch(message, status)
   116→        );
   117→        return this;
   118→    }
   119→
   120→    /**
   121→     * Verifies HTTP response status code against the provided matcher,
   122→     * and throws {@link AssertionError} in case of mismatch.
   123→     * @param matcher Matcher to validate status code
   124→     * @return This object
   125→     */
   126→    public RestResponse assertStatus(final Matcher<Integer> matcher) {
   127→        MatcherAssert.assertThat(
   128→            String.format(
   129→                "HTTP response status is not the one expected:%n%s",
   130→                this
   131→            ),
   132→            this.status(), matcher
   133→        );
   134→        return this;
   135→    }
   136→
   137→    /**
   138→     * Verifies HTTP response body content against provided matcher,
   139→     * and throws {@link AssertionError} in case of mismatch.
   140→     * @param matcher The matcher to use
   141→     * @return This object
   142→     */
   143→    public RestResponse assertBody(final Matcher<String> matcher) {
   144→        MatcherAssert.assertThat(
   145→            String.format(
   146→                "HTTP response body content is not valid:%n%s",
   147→                this
   148→            ),
   149→            this.body(), matcher
   150→        );
   151→        return this;
   152→    }
   153→
   154→    /**
   155→     * Verifies HTTP response body content against provided matcher,
   156→     * and throws {@link AssertionError} in case of mismatch.
   157→     * @param matcher The matcher to use
   158→     * @return This object
   159→     */
   160→    public RestResponse assertBinary(final Matcher<byte[]> matcher) {
   161→        MatcherAssert.assertThat(
   162→            String.format(
   163→                "HTTP response binary content is not valid:%n%s",
   164→                this
   165→            ), this.binary(),
   166→            matcher
   167→        );
   168→        return this;
   169→    }
   170→
   171→    /**
   172→     * Verifies HTTP header against provided matcher, and throws
   173→     * {@link AssertionError} in case of mismatch.
   174→     *
   175→     * <p>The iterator for the matcher will always be a real object an never
   176→     * {@code NULL}, even if such a header is absent in the response. If the
   177→     * header is absent the iterable will be empty.
   178→     *
   179→     * @param name Name of the header to match
   180→     * @param matcher The matcher to use
   181→     * @return This object
   182→     */
   183→    public RestResponse assertHeader(
   184→        final String name,
   185→        final Matcher<Iterable<String>> matcher
   186→    ) {
   187→        Iterable<String> values = this.headers().get(name);
   188→        if (values == null) {
   189→            values = Collections.emptyList();
   190→        }
   191→        MatcherAssert.assertThat(
   192→            String.format(
   193→                "HTTP header '%s' is not valid:%n%s",
   194→                name, this
   195→            ),
   196→            values, matcher
   197→        );
   198→        return this;
   199→    }
   200→
   201→    /**
   202→     * Verifies HTTP header against provided matcher, and throws
   203→     * {@link AssertionError} in case of mismatch.
   204→     * @param name Name of the header to match
   205→     * @param value The value to expect in one of the headers
   206→     * @return This object
   207→     * @since 0.9
   208→     */
   209→    public RestResponse assertHeader(final String name, final String value) {
   210→        return this.assertHeader(name, Matchers.hasItems(value));
   211→    }
   212→
   213→    /**
   214→     * Jump to a new location.
   215→     * @param uri Destination to jump to
   216→     * @return New request
   217→     */
   218→    @SuppressWarnings("PMD.UseConcurrentHashMap")
   219→    public Request jump(final URI uri) {
   220→        Request req = this.back().uri()
   221→            .set(this.back().uri().get().resolve(uri))
   222→            .back();
   223→        final Map<String, List<String>> headers = this.headers();
   224→        if (headers.containsKey(HttpHeaders.SET_COOKIE)) {
   225→            for (final String header : headers.get(HttpHeaders.SET_COOKIE)) {
   226→                for (final HttpCookie cookie : HttpCookie.parse(header)) {
   227→                    req = req.header(
   228→                        HttpHeaders.COOKIE,
   229→                        String.format(
   230→                            "%s=%s", cookie.getName(), cookie.getValue()
   231→                        )
   232→                    );
   233→                }
   234→            }
   235→        }
   236→        return req;
   237→    }
   238→
   239→    /**
   240→     * Follow LOCATION header.
   241→     * @return New request
   242→     */
   243→    public Request follow() {
   244→        this.assertHeader(
   245→            HttpHeaders.LOCATION,
   246→            Matchers.not(Matchers.emptyIterableOf(String.class))
   247→        );
   248→        return this.jump(
   249→            URI.create(this.headers().get(HttpHeaders.LOCATION).get(0))
   250→        );
   251→    }
   252→
   253→    /**
   254→     * Get one cookie by name.
   255→     * @param name Cookie name
   256→     * @return Cookie found
   257→     */
   258→    @SuppressWarnings("PMD.UseConcurrentHashMap")
   259→    public Cookie cookie(final String name) {
   260→        final Map<String, List<String>> headers = this.headers();
   261→        MatcherAssert.assertThat(
   262→            "cookies should be set in HTTP header",
   263→            headers.containsKey(HttpHeaders.SET_COOKIE)
   264→        );
   265→        final List<String> cookies = headers.get(HttpHeaders.SET_COOKIE);
   266→        final Iterator<String> iterator = cookies.iterator();
   267→        Cookie cookie = null;
   268→        while (iterator.hasNext()) {
   269→            final String obj = iterator.next();
   270→            for (final HttpCookie candidate : HttpCookie.parse(obj)) {
   271→                if (candidate.getName().equals(name)) {
   272→                    cookie = RestResponse.cookie(candidate);
   273→                    break;
   274→                }
   275→            }
   276→        }
   277→        MatcherAssert.assertThat(
   278→            Logger.format(
   279→                "cookie '%s' not found in Set-Cookie header: '%s'",
   280→                name,
   281→                cookies
   282→            ),
   283→            cookie,
   284→            Matchers.notNullValue()
   285→        );
   286→        assert cookie != null;
   287→        return cookie;
   288→    }
   289→
   290→    /**
   291→     * Convert HTTP cookie to a standard one.
   292→     * @param cookie HTTP cookie
   293→     * @return Regular one
   294→     */
   295→    private static Cookie cookie(final HttpCookie cookie) {
   296→        return new Cookie(
   297→            cookie.getName(),
   298→            cookie.getValue(),
   299→            cookie.getPath(),
   300→            cookie.getDomain(),
   301→            cookie.getVersion()
   302→        );
   303→    }
   304→
   305→    /**
   306→     * Status matcher.
   307→     *
   308→     * @since 1.2
   309→     */
   310→    private static final class StatusMatch extends CustomMatcher<Response> {
   311→
   312→        /**
   313→         * HTTP status to check.
   314→         */
   315→        private final transient int status;
   316→
   317→        /**
   318→         * Ctor.
   319→         * @param msg Message to show
   320→         * @param sts HTTP status to check
   321→         */
   322→        StatusMatch(final String msg, final int sts) {
   323→            super(msg);
   324→            this.status = sts;
   325→        }
   326→
   327→        @Override
   328→        public boolean matches(final Object resp) {
   329→            return Response.class.cast(resp).status() == this.status;
   330→        }
   331→    }
   332→
   333→}
