     * Matcher for URI rawPath property.
     * @param path The path matcher
     * @return Matcher for URI rawPath
     */
    private static Matcher<URI> hasRawPath(final Matcher<String> path) {
        return new TypeSafeMatcher<URI>() {
            @Override
            public void describeTo(final Description desc) {
                desc.appendText("URI with path ").appendDescriptionOf(path);
            }

            @Override
            protected boolean matchesSafely(final URI uri) {
                return path.matches(uri.getRawPath());
            }
        };
    }

